Ext._define('common.official_journal.JournalSuplementGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'common.official_journal.JournalSuplementWindow',
    hideItemsToolbar: ['edit', 'download'],
    hideActions: ['copy'],
    keywordFieldMessage: 'Digite o termo para busca e tecle Enter',
    actionColumnWidth: 90,

    title: 'Suplementos',

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    {header: 'Nome', dataIndex: 'name', id: 'autoExpandColumn'},
                    {header: 'Criado em', dataIndex: 'created_at', width: 100},
                    {header: 'Publicado em', dataIndex: 'published_date', width: 100, renderer: function(value) { return value || 'Não publicado'; }}
                ]
            );

        return this._columnModel;
    },

    getConfigActions: function()
    {
        var custom_actions = [
            {
                tooltip: 'Download do arquivo',
                getClass: function(val, meta, record)
                { return record.get('ged') ? 'icon-journal icon-download' : ''; },
                handler: function(action, index)
                {
                    var url = this.getStore().getAt(index).get('ged_uri');
                    window.open(url, '_blank');
                }
            },
            {
                tooltip: 'Publicar',
                getClass: function(v, meta, record, a, b)
                { return record.get('published_date') ? 'icon-journal icon-published' : 'icon-journal icon-no-published'; },
                handler: function(action, index) {
                    var grid = this,
                        store = grid.getStore(),
                        record = store.getAt(index),
                        rest = grid.factoryRestful();

                    if(!record.get('published_date'))
                    {
                        Ext.Msg.confirm(
                            'Atenção',
                            'Confirma a publicação do suplemento ' + record.get('name') + '?',
                            function(btn)
                            {
                                if(btn == 'yes')
                                {
                                    var mask = new Ext.LoadMask(grid.el, {msg: 'Processando...'});
                                    mask.show();

                                    Ext.Ajax.request({
                                        url: rest.uriFor('publish'),
                                        method: 'POST',
                                        success: function(response, opts)
                                        {
                                            mask.hide();

                                            var obj = Ext.decode(response.responseText);
                                            if(obj.success)
                                                store.reload();
                                            else
                                                Ext.Msg.alert('Erro', obj.message);
                                        },
                                        params: {pk: record.get('pk')}
                                    });
                                }
                            }
                        );
                    }
                    else
                        Ext.Msg.alert('Aviso', 'Diário '+ record.get('full_code') +' já está publicado.');
                }
            }
        ];

        return custom_actions.concat(
            common.official_journal.JournalSuplementGrid.superclass.getConfigActions.call(this)
        );
    }
});

core.RestfulGrid.register(
    'common.official_journal.JournalManageRestful',
    'common.official_journal.JournalSuplementGrid'
);

